/* Photo stickers that appear as matchable tiles (source PNGs in assets/stickers/). */
const Stickers = (() => {
  const SRC = {
  p1: 'data:image/png;base64,',
  p2: 'data:image/png;base64,',
  dog: 'data:image/png;base64,'
  };
  const img = {};
  const ready = Promise.all(Object.entries(SRC).map(([k, src]) => new Promise(res => {
    const i = new Image(); i.onload = i.onerror = () => res(); i.src = src; img[k] = i;
  })));
  return { img, ready };
})();
